const idxFecha = headers.indexOf('Fecha');
const idxTarea = headers.indexOf('Tarea');
const idxEstado = headers.indexOf('Estado');
const idxHora = headers.findIndex(h => h.toString().trim().startsWith('Hora'));

let completadas = 0;
let pendientes = 0;
let totalSemana = 0;
const porDia = {};
const diasNombre = ['Dom', 'Lun', 'Mar', 'Mi\u00e9', 'Jue', 'Vie', 'S\u00e1b'];

for (const fila of data) {
  const fechaStr = (fila[idxFecha] || '').toString().trim();
  if (!fechaStr) continue;

  const fecha = new Date(fechaStr + 'T12:00:00');
  if (fecha < lunes || fecha > domingo) continue;

  totalSemana++;
  const estado = (fila[idxEstado] || '').toString().trim().toLowerCase();
  const dia = diasNombre[fecha.getDay()];

  if (!porDia[dia]) porDia[dia] = { completadas: 0, pendientes: 0 };

  if (estado === 'hecho' || estado === 'completada') {
    completadas++;
    porDia[dia].completadas++;
  } else {
    pendientes++;
    porDia[dia].pendientes++;
  }
}

const porcentaje = totalSemana > 0 ? Math.round((completadas / totalSemana) * 100) : 0;

let mejorDia = '';
let mejorCount = 0;
for (const [dia, stats] of Object.entries(porDia)) {
  if (stats.completadas > mejorCount) {
    mejorCount = stats.completadas;
    mejorDia = dia;
  }
}

return [{ json: {
  completadas,
  pendientes,
  totalSemana,
  porcentaje,
  mejorDia,
  mejorCount,
  porDia,
  lunesStr: lunes.toISOString().split('T')[0],
  domingoStr: domingo.toISOString().split('T')[0]
}}];

